// 自定义拼写纠错（localStorage 扩展）
function loadCustomSpelling() {
  try { return JSON.parse(localStorage.getItem('customSpelling') || '[]'); }
  catch { return []; }
}
function saveCustomSpelling(list) {
  localStorage.setItem('customSpelling', JSON.stringify(list));
}

