// 检查两个词是否在假同源词黑名单中
function isFalseEtymology(word1, word2) {
  const w1 = word1.toLowerCase().trim();
  const w2 = word2.toLowerCase().trim();
  const blocked = FALSE_ETYMOLOGY_PAIRS[w1];
  return blocked ? blocked.includes(w2) : false;
}

